import{_ as r,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Manage customers","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/quotations-orders/manage-customers.md","filePath":"master/sales/sales/quotations-orders/manage-customers.md","lastUpdated":1793074831000}'),l={name:"master/sales/sales/quotations-orders/manage-customers.md"};function c(u,e,m,g,h,d){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="manage-customers" tabindex="-1">Manage customers <a class="header-anchor" href="#manage-customers" aria-label="Permalink to &quot;Manage customers&quot;">​</a></h1><p>A customer is a person or a company you sell to. You create the customer once. After that you pick them on every quotation, and Aureus fills in their address, payment terms and salesperson for you. This saves typing and keeps your records tidy.</p><blockquote><p><strong>In simple words:</strong> The customer record is the address book entry for the people you sell to.</p></blockquote><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Customers and Contacts are the same records. A customer you add here also appears in <strong>Contacts</strong>, and the other way round. This page covers what matters for selling. For the full contact fields, see <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open <code>Sales → Orders → Customers</code>. The list shows the name, email, phone, account type, job title and industry of each customer.</p><p>Use the tabs above the list:</p><ul><li><strong><em>Default:</em></strong> All customers.</li><li><strong><em>Individuals:</em></strong> Customers who are people.</li><li><strong><em>Companies:</em></strong> Customers who are businesses.</li><li><strong><em>Archived:</em></strong> Customers you deleted. You can bring them back from here.</li></ul><p>Use <strong>Group by</strong> to group the list by <strong>Account Type</strong>, <strong>Parent</strong>, <strong>Title</strong>, <strong>Job Title</strong> or <strong>Industry</strong>. For example, group by <strong>Industry</strong> to see all your retail customers together. For search and filter tips, see <a href="./../../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><p>Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong> actions.</p><h2 id="create-a-customer" tabindex="-1">Create a customer <a class="header-anchor" href="#create-a-customer" aria-label="Permalink to &quot;Create a customer&quot;">​</a></h2><p>Example: your company sells office furniture. A new client, Brightway Offices, asks for a quote. You add Brightway as a company first. Then you add Priya, the person who orders for them.</p><ol><li>Go to <code>Sales → Orders → Customers</code>.</li><li>Click <strong>Create Customer</strong>.</li></ol>',13)),s(o,{src:"/images1/sales/customers_list.png",alt:"Customers list with the Customers menu and the New Customer button"}),e[1]||(e[1]=t('<ol start="3"><li>Fill in the form. Only the name is needed to save. The other fields help you later.</li></ol><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Individual or Company:</em></strong> Choose the type. Pick <strong>Company</strong> for a business such as Brightway Offices. Pick <strong>Individual</strong> for a person. When you choose <strong>Company</strong>, the <strong>Company</strong> field is hidden.</li><li><strong><em>Name:</em></strong> The full name of the person or company.</li><li><strong><em>Company:</em></strong> For a person, the company they work for. Choose one from the list, or create it on the spot. Priya would get &quot;Brightway Offices&quot; here.</li><li><strong><em>Tax ID:</em></strong> The tax or VAT number. It prints on the invoice, so add it for business customers.</li><li><strong><em>Job Title:</em></strong> The person&#39;s role, such as Purchase Manager.</li><li><strong><em>Phone</em></strong> and <strong><em>Mobile:</em></strong> The numbers you call.</li><li><strong><em>Email:</em></strong> Where Aureus sends quotations. Check it carefully.</li><li><strong><em>Website:</em></strong> The customer&#39;s web address.</li><li><strong><em>Title:</em></strong> A form of address, such as Mr or Dr.</li><li><strong><em>Tags:</em></strong> Labels to group customers, such as &quot;Wholesale&quot;. See <a href="./../configuration/tags.html">Tags</a>.</li><li><strong><em>Address:</em></strong> Street, city, zip code, state and country.</li></ul>',3)),s(o,{src:"/images1/sales/customer_create_general.png",alt:"Create Customer page, General section filled in"}),e[2]||(e[2]=t('<h3 id="sales-and-purchases" tabindex="-1">Sales and Purchases <a class="header-anchor" href="#sales-and-purchases" aria-label="Permalink to &quot;Sales and Purchases&quot;">​</a></h3><p>This section sets the defaults that Aureus copies onto a new quotation for this customer.</p><p><strong>Sales</strong></p><ul><li><strong><em>Responsible:</em></strong> The team member who looks after this customer. Pick yourself, for example.</li><li><strong><em>Price List:</em></strong> The price list Aureus uses for this customer. It shows only when <strong>Price Lists</strong> is on.</li><li><strong><em>Payment Terms:</em></strong> When the customer must pay after you invoice. For example, &quot;30 Days&quot; means payment is due 30 days after the invoice date. You can change it on each quotation. To create new terms, see <a href="./../../../finance/customer-invoices/payment-terms.html">Payment terms</a>.</li><li><strong><em>Payment Method:</em></strong> How the customer usually pays, such as bank transfer.</li></ul><p><strong>Purchase</strong></p><p>Fill this only if you also buy from this customer.</p><ul><li><strong><em>Payment Terms:</em></strong> When you pay them.</li><li><strong><em>Payment Method:</em></strong> How you pay them.</li></ul><p><strong>Fiscal Information</strong></p><ul><li><strong><em>Fiscal Position:</em></strong> Tax rules for this customer. Use it when taxes change by region, for example for customers abroad.</li></ul><p><strong>Others</strong></p><ul><li><strong><em>Company ID:</em></strong> Your own internal code.</li><li><strong><em>Reference:</em></strong> Another code, such as a customer number.</li><li><strong><em>Industry:</em></strong> The business sector. You can group the list by it.</li></ul>',11)),s(o,{src:"/images1/sales/customer_create_sales.png",alt:"Sales and Purchases tab with Responsible, Payment Terms, Payment Method and Price List filled in"}),e[3]||(e[3]=t('<h3 id="invoicing" tabindex="-1">Invoicing <a class="header-anchor" href="#invoicing" aria-label="Permalink to &quot;Invoicing&quot;">​</a></h3><p><strong>Customer Invoices</strong></p><ul><li><strong><em>Invoice Sending Method:</em></strong> How invoices reach this customer: <strong>Download</strong>, <strong>Email</strong> or <strong>Post</strong>.</li><li><strong><em>eInvoice Format:</em></strong> The electronic invoice format to use, if your customer needs one.</li></ul><p><strong>Accounting Entries</strong></p><ul><li><strong><em>Account Receivable:</em></strong> The account used for what the customer owes you. It is filled for you.</li><li><strong><em>Account Payable:</em></strong> The account used for what you owe the customer. It is filled for you.</li></ul><p><strong>Automation</strong></p><ul><li><strong><em>Auto Post Bills:</em></strong> Choose <strong>Always</strong>, <strong>Ask after 3 validations without edit</strong> or <strong>Never</strong>.</li><li><strong><em>Ignore Abnormal Invoice Amount:</em></strong> Skips the warning for unusual invoice amounts.</li><li><strong><em>Ignore Abnormal Invoice Date:</em></strong> Skips the warning for unusual invoice dates.</li></ul><p>If you are unsure, leave these on their defaults.</p><ol start="4"><li>Click <strong>Create</strong>. Click <strong>Create &amp; create another</strong> to add more customers, or <strong>Cancel</strong> to leave.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also create a customer without leaving a quotation. Click the plus icon next to <strong>Customer</strong>.</p></div>',10)),s(o,{src:"/images1/sales/customer_create_invoicing.png",alt:"Invoicing tab with invoice sending method, accounting entries and automation"}),e[4]||(e[4]=t('<h2 id="after-you-create-a-customer" tabindex="-1">After you create a customer <a class="header-anchor" href="#after-you-create-a-customer" aria-label="Permalink to &quot;After you create a customer&quot;">​</a></h2><p>Aureus opens the customer page. Click <strong>Edit</strong> to change the record. The tabs on this page let you add contacts, addresses and bank accounts.</p><h3 id="contacts" tabindex="-1">Contacts <a class="header-anchor" href="#contacts" aria-label="Permalink to &quot;Contacts&quot;">​</a></h3><p>Use this tab for the people you deal with at a company. Priya, Brightway&#39;s buyer, is one example.</p><ol><li>Open the <strong>Contacts</strong> tab.</li><li>Click <strong>Add Contact</strong>.</li><li>Fill in the form. It has the same fields as a new customer.</li><li>Save the contact.</li></ol>',5)),s(o,{src:"/images1/sales/customer_view.png",alt:"Customer page with the View, Edit, Contacts, Addresses and Bank Accounts tabs"}),e[5]||(e[5]=t('<h3 id="address" tabindex="-1">Address <a class="header-anchor" href="#address" aria-label="Permalink to &quot;Address&quot;">​</a></h3><p>Use this tab when one customer has more than one place. Brightway may want invoices sent to head office and goods sent to a warehouse.</p><ol><li>Open the <strong>Address</strong> tab.</li><li>Click <strong>Add Address</strong>.</li><li>Choose the address type: <strong>Permanent</strong>, <strong>Present</strong>, <strong>Invoice</strong>, <strong>Delivery</strong> or <strong>Other</strong>.</li><li>Enter the <strong>Name</strong>, <strong>Email</strong>, <strong>Phone</strong>, <strong>Mobile</strong> and the full address.</li><li>Save the address.</li></ol><h3 id="bank-accounts" tabindex="-1">Bank accounts <a class="header-anchor" href="#bank-accounts" aria-label="Permalink to &quot;Bank accounts&quot;">​</a></h3><p>Use this tab to keep the customer&#39;s bank details, for example to refund them later.</p><ol><li><p>Open the <strong>Bank Account</strong> tab.</p></li><li><p>Click <strong>New Bank Account</strong>.</p></li><li><p>Fill in the form:</p><ul><li><strong><em>Account Number:</em></strong> The bank account number.</li><li><strong><em>Can Send Money:</em></strong> Turn this on if you can pay money into this account.</li><li><strong><em>Bank:</em></strong> Choose a bank, or create one with the plus icon.</li><li><strong><em>Account Holder:</em></strong> The customer the account belongs to.</li></ul></li><li><p>Save the account.</p></li></ol><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit:</strong> Change any field. Click <strong>Save changes</strong> when done.</li><li><strong>Delete:</strong> Moves the customer to the <strong>Archived</strong> tab. Old quotations keep their customer name.</li><li><strong>Restore:</strong> From <strong>Archived</strong>, bring a customer back into the active list.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Check the <strong>Email</strong> and <strong>Payment Terms</strong> before you send the first quotation. A wrong email means the customer never gets it. Wrong terms put the wrong due date on the invoice.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-quotation.html">Create a quotation</a></li><li><a href="./">Quotations and orders</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li><li><a href="./../configuration/tags.html">Tags</a></li><li><a href="./../../../finance/customer-invoices/payment-terms.html">Payment terms</a></li></ul>',11))])}const y=r(l,[["render",c]]);export{f as __pageData,y as default};
